import { test, expect } from '@playwright/test';

test.describe('Search Filter', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display "No results" message when search yields no results', async ({ page }) => {
    await page.fill(getByLabel('Search'), 'nonexistent item'); // Replace with the actual label
    await page.click(getByRole('button', { name: 'Search' })); // Replace with the actual button name
    const noResultsMessage = await page.getByText('No results found'); // Replace with the actual message
    await expect(noResultsMessage).toBeVisible();
  });

  test('should not display "No results" message when search yields results', async ({ page }) => {
    await page.fill(getByLabel('Search'), 'existing item'); // Replace with the actual label and item
    await page.click(getByRole('button', { name: 'Search' })); // Replace with the actual button name
    const noResultsMessage = page.getByText('No results found'); // Replace with the actual message
    await expect(noResultsMessage).not.toBeVisible();
  });
});
